import{_ as o,a0 as l,w as r,s as d,ao as p,I as i,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"awk 系列：如何使用 awk 复合表达式 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 复合表达式 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 复合表达式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 复合表达式 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 5 - How to Use Compound Expressions with Awk in Linux","title":"awk 系列：如何使用 awk 复合表达式","tag":"awk","desc":""},"relativePath":"awk/Part 5 - How to Use Compound Expressions with Awk in Linux.md","filePath":"[post].md"}'),k={name:"awk/Part 5 - How to Use Compound Expressions with Awk in Linux.md"};function c(u,s,h,w,m,g){const t=l("Link");return r(),d("div",null,[s[16]||(s[16]=p('<h1 id="awk-系列-如何使用-awk-复合表达式" tabindex="-1">awk 系列：如何使用 awk 复合表达式 <a class="header-anchor" href="#awk-系列-如何使用-awk-复合表达式" aria-label="Permalink to “awk 系列：如何使用 awk 复合表达式”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Use-Compound-Expressions-with-Awk.png" alt=""></p><p>一直以来在查对条件是否匹配时，我们使用的都是简单的表达式。那如果你想用超过一个表达式来查对特定的条件呢？</p><p>本文，我们将看看如何在过滤文本和字符串时，结合多个表达式，即复合表达式，用以查对条件。</p><p>awk 的复合表达式可由表示“与”的组合操作符 <code>&amp;&amp;</code> 和表示“或”的 <code>||</code> 构成。</p><p>复合表达式的常规写法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>( 第一个表达式 ) &amp;&amp; ( 第二个表达式 )</span></span></code></pre></div><p>这里只有当“第一个表达式” 和“第二个表达式”都是真值时整个表达式才为真。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>( 第一个表达式 ) || ( 第二个表达式)</span></span></code></pre></div><p>这里只要“第一个表达式” 为真或“第二个表达式”为真，整个表达式就为真。</p><p><strong>注意</strong>：切记要加括号。</p>',11)),i("p",null,[s[1]||(s[1]=a("表达式可以由比较操作符构成，具体可查看",-1)),e(t,{href:"https://linux.cn/article-7602-1.html"},{default:n(()=>[...s[0]||(s[0]=[a(" awk 系列的第四节",-1)])]),_:1}),s[2]||(s[2]=a("。",-1))]),s[17]||(s[17]=p(`<p>现在让我们通过一个例子来加深理解：</p><p>此例中，有一个文本文件 <code>tecmint_deals.txt</code>，文本中包含着一张随机的 Tecmint 交易清单，其中包含了名称、价格和种类。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TecMint Deal List</span></span>
<span class="line"><span>No      Name                                    Price           Type</span></span>
<span class="line"><span>1       Mac_OS_X_Cleanup_Suite                  $9.99           Software</span></span>
<span class="line"><span>2       Basics_Notebook                         $14.99          Lifestyle</span></span>
<span class="line"><span>3       Tactical_Pen                            $25.99          Lifestyle</span></span>
<span class="line"><span>4       Scapple                                 $19.00          Unknown</span></span>
<span class="line"><span>5       Nano_Tool_Pack                          $11.99          Unknown</span></span>
<span class="line"><span>6       Ditto_Bluetooth_Altering_Device         $33.00          Tech</span></span>
<span class="line"><span>7       Nano_Prowler_Mini_Drone                 $36.99          Tech</span></span></code></pre></div><p>我们只想打印出价格超过 $20 且其种类为 “Tech” 的物品，在其行末用 (*) 打上标记。</p><p>我们将要执行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;($3 ~ /^\\$[2-9][0-9]*\\.[0-9][0-9]$/) &amp;&amp; ($4==&quot;Tech&quot;) { printf &quot;%s\\t%s\\n&quot;,$0,&quot;*&quot;; } &#39; tecmint_deals.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>6	Ditto_Bluetooth_Altering_Device		$33.00		Tech	*</span></span>
<span class="line"><span>7	Nano_Prowler_Mini_Drone			$36.99          Tech	 *</span></span></code></pre></div><p>此例，在复合表达式中我们使用了两个表达式：</p><ul><li>表达式 1：<code>($3 ~ /^\\$[2-9][0-9]*\\.[0-9][0-9]$/)</code> ；查找交易价格超过 <code>$20</code> 的行，即只有当 <code>$3</code> 也就是价格满足 <code>/^\\$[2-9][0-9]*\\.[0-9][0-9]$/</code> 时值才为真值。</li><li>表达式 2：<code>($4 == “Tech”)</code> ；查找是否有种类为 “<code>Tech</code>”的交易，即只有当 <code>$4</code> 等于 “<code>Tech</code>” 时值才为真值。 切记，只有当 <code>&amp;&amp;</code> 操作符的两端状态，也就是两个表达式都是真值的情况下，这一行才会被打上 <code>(*)</code> 标志。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>有些时候为了真正符合你的需求，就不得不用到复合表达式。当你掌握了比较和复合表达式操作符的用法之后，复杂的文本或字符串过滤条件也能轻松解决。</p><p>希望本向导对你有所帮助，如果你有任何问题或者补充，可以在下方发表评论，你的问题将会得到相应的解释。</p><hr>`,12)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),e(t,{href:"http://www.tecmint.com/combine-multiple-expressions-in-awk/"},{default:n(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/combine-multiple-expressions-in-awk/",-1)])]),_:1})]),i("p",null,[s[8]||(s[8]=a("作者：",-1)),e(t,{href:"http://www.tecmint.com/author/aaronkili/"},{default:n(()=>[...s[5]||(s[5]=[a("Aaron Kili",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),e(t,{href:"https://github.com/martin2011qi"},{default:n(()=>[...s[6]||(s[6]=[a("martin2011qi",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const b=o(k,[["render",c]]);export{f as __pageData,b as default};
